"use client";

import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import {
  Loader2,
  LayoutDashboard,
  ShoppingBag,
  User,
  Store,
  Menu,
  X,
  LogOut,
  LayoutGrid,
  Coins,
  LifeBuoy,
  Heart,
  Settings,
} from "lucide-react";
import { claimGuestOrdersForSession } from "@/lib/claimGuestOrders";
import { fetchOnboardingContext, getAccountOnboardingContinuePath } from "@/lib/onboardingState";

type Me = { name: string; logoUrl: string | null; hasStore: boolean; isSellerFlag: boolean };

export default function AccountLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const pathname = usePathname();
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [sellerStoreId, setSellerStoreId] = useState<string | null>(null);
  const [me, setMe] = useState<Me | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        router.replace("/login");
        return;
      }

      const [{ data: store }, { data: profile }] = await Promise.all([
        supabase.from("stores").select("id").eq("owner_id", user.id).maybeSingle(),
        supabase
          .from("profiles")
          .select(
            "phone_number, display_name, full_name, logo_url, is_seller, onboarding_completed, onboarding_step, buyer_interested_categories, slug, location_state, location_city, location"
          )
          .eq("id", user.id)
          .maybeSingle(),
      ]);

      if (cancelled) return;

      const ctx = await fetchOnboardingContext(supabase, user.id);
      const resume = getAccountOnboardingContinuePath(ctx, ctx.profile);
      if (resume.startsWith("/onboarding")) {
        router.replace(resume);
        return;
      }

      const p = profile as {
        phone_number?: string | null;
        display_name?: string | null;
        full_name?: string | null;
        logo_url?: string | null;
        is_seller?: boolean | null;
      } | null;

      await claimGuestOrdersForSession(supabase, {
        userId: user.id,
        email: user.email ?? null,
        phoneDigits: p?.phone_number ?? null,
      });

      const hasStore = !!store?.id;
      setSellerStoreId(store?.id ?? null);
      setMe({
        name: p?.display_name?.trim() || p?.full_name?.trim() || user.email?.split("@")[0] || "Account",
        logoUrl: p?.logo_url?.trim() || null,
        hasStore,
        isSellerFlag: !!p?.is_seller,
      });
      setLoading(false);
    })();

    return () => {
      cancelled = true;
    };
  }, [router]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    window.location.assign("/login");
  };

  const links = useMemo(() => {
    const base: { name: string; href: string; icon: typeof LayoutDashboard }[] = [
      { name: "Overview", href: "/account", icon: LayoutDashboard },
    ];
    if (me?.isSellerFlag) {
      base.push(
        { name: "Sales & inventory", href: "/dashboard", icon: LayoutGrid },
        { name: "Manage orders", href: "/dashboard/orders", icon: ShoppingBag },
        { name: "Verification", href: "/dashboard/verification", icon: User },
        { name: "Membership & payouts", href: "/dashboard/subscription", icon: Coins },
        { name: "Seller settings", href: "/dashboard/settings", icon: User },
      );
    }
    base.push(
      { name: "My purchases", href: "/account/orders", icon: ShoppingBag },
      { name: "My wallet", href: "/account/wallet", icon: Coins },
      { name: "Wishlist", href: "/account/wishlist", icon: Heart },
      { name: "Profile", href: "/account/profile", icon: User },
      { name: "Settings", href: "/account/settings", icon: Settings },
      { name: "Help & support", href: "/account/support", icon: LifeBuoy },
    );
    if (!sellerStoreId) {
      base.push({ name: "Start selling", href: "/account/start-selling", icon: Store });
    }
    return base;
  }, [sellerStoreId, me?.isSellerFlag]);

  if (loading || !me) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <aside
        className={`fixed inset-y-0 left-0 z-40 w-72 bg-white border-r border-gray-100 transform transition-transform md:translate-x-0 md:static ${
          open ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="p-6 border-b border-gray-100 flex items-center justify-between md:block">
          <div>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">StoreLink</p>
            <p className="font-black text-lg text-gray-900 uppercase tracking-tighter mt-1">
              {me.isSellerFlag ? "Seller account" : "My account"}
            </p>
            <div className="flex items-center gap-3 mt-4">
              <div className="w-11 h-11 rounded-2xl overflow-hidden bg-gray-100 border border-gray-100 shrink-0 flex items-center justify-center">
                {me.logoUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={me.logoUrl} alt="" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-sm font-black text-gray-400 uppercase">{me.name.slice(0, 1)}</span>
                )}
              </div>
              <div className="min-w-0">
                <p className="font-bold text-gray-900 text-sm truncate">{me.name}</p>
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {me.hasStore && (
                    <span className="text-[9px] font-black uppercase tracking-wider text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md">
                      Seller
                    </span>
                  )}
                  {!me.hasStore && me.isSellerFlag && (
                    <span className="text-[9px] font-black uppercase tracking-wider text-gray-500 bg-gray-100 px-2 py-0.5 rounded-md">
                      Seller profile
                    </span>
                  )}
                  {!me.isSellerFlag && !me.hasStore && (
                    <span className="text-[9px] font-black uppercase tracking-wider text-gray-500 bg-gray-100 px-2 py-0.5 rounded-md">
                      Shopper
                    </span>
                  )}
                </div>
              </div>
            </div>
            <p className="text-[10px] text-gray-400 font-medium mt-4 leading-snug">
              {me.hasStore
                ? "Your storefront, orders, wallet, and profile — all in one place."
                : "Your orders, Store Coins, and profile."}
            </p>
          </div>
          <button type="button" className="md:hidden p-2 rounded-xl bg-gray-50" onClick={() => setOpen(false)}>
            <X size={18} />
          </button>
        </div>
        <nav className="p-4 space-y-1">
          {links.map((l) => {
            const active =
              l.href === "/account"
                ? pathname === "/account"
                : pathname === l.href || pathname.startsWith(l.href + "/");
            const Icon = l.icon;
            return (
              <Link
                key={l.href + l.name}
                href={l.href}
                onClick={() => setOpen(false)}
                className={`flex items-center gap-3 px-4 py-3 rounded-2xl text-sm font-bold transition-all ${
                  active ? "bg-gray-900 text-white shadow-lg" : "text-gray-600 hover:bg-gray-50"
                }`}
              >
                <Icon size={18} />
                {l.name}
              </Link>
            );
          })}
        </nav>
        <div className="p-4 mt-auto border-t border-gray-100">
          <button
            type="button"
            onClick={handleLogout}
            className="flex items-center gap-3 w-full px-4 py-3 rounded-2xl text-sm font-bold text-red-600 hover:bg-red-50 transition"
          >
            <LogOut size={18} />
            Log out
          </button>
        </div>
      </aside>

      {open && (
        <button type="button" className="fixed inset-0 bg-black/40 z-30 md:hidden" aria-label="Close menu" onClick={() => setOpen(false)} />
      )}

      <div className="flex-1 flex flex-col min-w-0">
        <header className="sticky top-0 z-20 bg-white/90 backdrop-blur border-b border-gray-100 px-4 py-4 flex items-center gap-3 md:hidden">
          <button type="button" className="p-2 rounded-xl bg-gray-50" onClick={() => setOpen(true)}>
            <Menu size={20} />
          </button>
          <span className="font-black text-sm uppercase tracking-tighter text-gray-900">Account</span>
        </header>
        <main className="flex-1 p-6 md:p-10 max-w-4xl w-full mx-auto">{children}</main>
      </div>
    </div>
  );
}
